import{_ as a,o as s,c as n,a2 as i}from"./chunks/framework.BxL9yGGP.js";const u=JSON.parse('{"title":"External Sentinel","description":"","frontmatter":{},"headers":[],"relativePath":"sentinel.md","filePath":"sentinel.md","lastUpdated":null}'),t={name:"sentinel.md"};function l(r,e,o,p,d,h){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="external-sentinel" tabindex="-1">External Sentinel <a class="header-anchor" href="#external-sentinel" aria-label="Permalink to &quot;External Sentinel&quot;">​</a></h1><p>External Sentinel is the VPS-side external watcher, separate from Homelab Console. It covers the failure mode where the console, WireGuard path, or home network is unreachable and the normal watcher stack cannot report its own outage.</p><p>The independently releasable HTTP, persistence and compatibility boundary is frozen in <a href="./sentinel-contract-v1"><code>sentinel-contract-v1.md</code></a>.</p><p>Treat it as a dead-man switch, not a second control plane. It observes from the outside, deduplicates locally, and sends Telegram alerts directly from the VPS. Its automatic Telegram alerts and recoveries use US English; historical or user-provided content is not translated.</p><h2 id="released-runtime" tabindex="-1">Released runtime <a class="header-anchor" href="#released-runtime" aria-label="Permalink to &quot;Released runtime&quot;">​</a></h2><p>The implementation, standalone tests, deployment assets and operator runbook live in <a href="https://github.com/imdelmare/homelab-console-sentinel" target="_blank" rel="noreferrer"><code>imdelmare/homelab-console-sentinel</code></a>. The first independently verified release is <a href="https://github.com/imdelmare/homelab-console-sentinel/releases/tag/v1.0.0" target="_blank" rel="noreferrer"><code>v1.0.0</code></a>. It provides:</p><ul><li>fixed-config HTTP health checks;</li><li>heartbeat receiver at <code>POST /heartbeat/{source_id}</code>;</li><li>heartbeat timeout detection;</li><li>local SQLite incident deduplication;</li><li>configurable consecutive-failure confirmation (three HTTP failures by default; heartbeat timeout remains one already-debounced failure);</li><li>two consecutive healthy observations before recovery;</li><li>persistent cross-source aggregation and cooldown in local SQLite;</li><li>one Telegram alert/recovery per availability group.</li></ul><p>The Sentinel does not call Homelab Console APIs, execute shell commands, forward raw HTTP requests, or remediate anything. URLs are read from local config at startup; runtime callers cannot provide arbitrary targets.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Use the configuration and environment templates shipped with the matching external release. Environment variables override the token, bind address, port, state path and Telegram credentials. Keep real values out of both repositories.</p><p>Heartbeat clients call:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /heartbeat/home</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;SENTINEL_HEARTBEAT_TOKEN&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>GET /health</code> only reports the Sentinel process liveness.</p><p>The default policy checks every 30 seconds, confirms HTTP failures after three samples, waits 120 seconds to aggregate correlated HTTP and heartbeat evidence, requires two healthy samples for recovery, and suppresses group reopenings for 30 minutes. Targets that represent the same availability boundary should share the same <code>notification_group</code>.</p><h2 id="deployment-shape" tabindex="-1">Deployment Shape <a class="header-anchor" href="#deployment-shape" aria-label="Permalink to &quot;Deployment Shape&quot;">​</a></h2><p>Use two deployments:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VPS</span></span>
<span class="line"><span>  External Sentinel</span></span>
<span class="line"><span>  Telegram direct alerting</span></span>
<span class="line"><span>  SQLite sentinel state</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Proxmox cluster / home side</span></span>
<span class="line"><span>  Homelab Console API/web/db</span></span>
<span class="line"><span>  internal watchers/providers/MCP</span></span>
<span class="line"><span>  outbound heartbeat sender to the VPS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Run Sentinel under systemd or Docker on the VPS. Bind the heartbeat listener to the VPS WireGuard address when the home side can reach it privately. Do not expose a public Sentinel hostname unless there is a specific reason to cross the public internet. If exposed, keep the bearer token mandatory and move signed heartbeats into Milestone 3 before relying on it across an untrusted path.</p><p>For a VPS-only Docker deployment, check out an exact release and follow its installation guide:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.0.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/imdelmare/homelab-console-sentinel.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> homelab-console-sentinel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.sentinel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Keep the filled <code>.env.sentinel</code> on the VPS only. Preserve the mounted <code>config/</code> and <code>data/</code> directories when replacing or rolling back the container.</p><p>The current lab deployment is a direct Docker deployment on the VPS. Preserve the mounted <code>config/</code> and <code>data/</code> directories when replacing the container.</p><p>On the home side, ADR 0023 allows the FastAPI lifecycle to send the heartbeat every 60 seconds. The origin and source id come only from <code>providers.vps.sentinel_heartbeat</code>; the token comes from the untracked <code>SENTINEL_HEARTBEAT_TOKEN</code> environment value. Enable it with <code>SENTINEL_HEARTBEAT_ENABLED=true</code>. It is a fixed background integration, not a tool or request-driven HTTP proxy.</p><p>The external repository&#39;s runbook still owns Sentinel health, failure, persistence and rollback drills. This core repository retains the versioned contract and the narrow heartbeat client only.</p><h2 id="later-milestones" tabindex="-1">Later Milestones <a class="header-anchor" href="#later-milestones" aria-label="Permalink to &quot;Later Milestones&quot;">​</a></h2><p>Milestone 2 should add a narrow Homelab Console integration: an External Sentinel page, typed import of Sentinel incidents, WireGuard status from the existing VPS provider, and last-heartbeat display.</p><p>Milestone 3 should add signed heartbeats, richer Telegram retry/backoff, retention, metrics and real failure drills.</p>`,27)])])}const m=a(t,[["render",l]]);export{u as __pageData,m as default};
